class Cell:
    def __init__(self):
        self._callbacks = []
        self._dependents = []

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

    def _fire_callbacks(self, value):
        for callback in self._callbacks:
            callback(value)


class InputCell(Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        _propagate(self)


class ComputeCell(Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = inputs
        self._compute_function = compute_function
        for cell in inputs:
            cell._dependents.append(self)
        self._value = self._compute_function([cell.value for cell in inputs])

    @property
    def value(self):
        return self._value

    def _recompute(self):
        self._value = self._compute_function([cell.value for cell in self._inputs])


def _propagate(changed_cell):
    # Collect every compute cell transitively affected by the change.
    dirty = set()
    stack = list(changed_cell._dependents)
    while stack:
        cell = stack.pop()
        if cell not in dirty:
            dirty.add(cell)
            stack.extend(cell._dependents)

    # Recompute in dependency order, firing callbacks only when a cell's
    # value actually changed from the previous stable state.
    remaining = set(dirty)
    while remaining:
        progressed = False
        for cell in list(remaining):
            if all(dep not in remaining for dep in cell._inputs):
                remaining.remove(cell)
                old_value = cell._value
                cell._recompute()
                if cell._value != old_value:
                    cell._fire_callbacks(cell._value)
                progressed = True
        if not progressed:
            break  # dependency cycle; leave remaining cells as-is

